module guitar_hero_max_score (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] num_notes,\n    input wire [3:0] note0,\n    input wire [3:0] note1,\n    input wire [3:0] note2,\n    input wire [3:0] note3,\n    input wire [1:0] num_phrases,\n    input wire [3:0] phrase0_start,\n    input wire [3:0] phrase0_end,\n    input wire [3:0] phrase1_start,\n    input wire [3:0] phrase1_end,\n    output reg [3:0] max_score,\n    output reg done\n);\n    \n    // State declarations\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] ITER_SUBSET  = 3'd1;\n    localparam [2:0] ITER_T       = 3'd2;\n    localparam [2:0] CHECK_OVERLAP = 3'd3;\n    localparam [2:0] FINISH       = 3'd4;\n    \n    reg [2:0] current_state;\n    \n    // Internal registers\n    reg [1:0] current_subset;\n    reg [3:0] T_counter;\n    reg [4:0] current_C;\n    reg [3:0] max_extra;\n    reg [3:0] base_score;\n    \n    // Combinational signals\n    wire subset_valid;\n    wire [4:0] C_subset;\n    wire any_overlap;\n    wire [3:0] current_count;\n    \n    // Note coverage calculation\n    wire note0_active = (0 < num_notes) ? ((T_counter <= note0) && (note0 < (T_counter + current_C))) : 1'b0;\n    wire note1_active = (1 < num_notes) ? ((T_counter <= note1) && (note1 < (T_counter + current_C))) : 1'b0;\n    wire note2_active = (2 < num_notes) ? ((T_counter <= note2) && (note2 < (T_counter + current_C))) : 1'b0;\n    wire note3_active = (3 < num_notes) ? ((T_counter <= note3) && (note3 < (T_counter + current_C))) : 1'b0;\n    \n    assign current_count = note0_active + note1_active + note2_active + note3_active;\n    \n    // Overlap detection\n    wire valid_phrase0 = current_subset[0] && (num_phrases >= 2'd1);\n    wire valid_phrase1 = current_subset[1] && (num_phrases >= 2'd2);\n    \n    wire overlap_phrase0 = valid_phrase0 && (T_counter < (phrase0_end + 4'd1)) && ((T_counter + current_C) > phrase0_start);\n    wire overlap_phrase1 = valid_phrase1 && (T_counter < (phrase1_end + 4'd1)) && ((T_counter + current_C) > phrase1_start);\n    assign any_overlap = overlap_phrase0 || overlap_phrase1;\n    \n    // Subset C calculation\n    assign C_subset =\n        (current_subset == 2'd0) ? 5'd0 :\n        (current_subset == 2'd1) ? (phrase0_end - phrase0_start) :\n        (current_subset == 2'd2) ? (phrase1_end - phrase1_start) :\n        (current_subset == 2'd3) ? (phrase0_end - phrase0_start) + (phrase1_end - phrase1_start) : 5'd0;\n    \n    assign subset_valid =\n        (current_subset == 2'd0) ? 1'b1 :\n        (current_subset == 2'd1) ? (num_phrases >= 2'd1) :\n        (current_subset == 2'd2) ? (num_phrases >= 2'd2) :\n        (current_subset == 2'd3) ? (num_phrases == 2'd2) : 1'b0;\n    \n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            current_state <= IDLE;\n            current_subset <= 2'd0;\n            T_counter <= 4'd0;\n            max_extra <= 4'd0;\n            done <= 1'b0;\n            max_score <= 4'd0;\n            base_score <= 4'd0;\n            current_C <= 5'd0;\n        end else begin\n            case (current_state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        current_subset <= 2'd0;\n                        base_score <= num_notes;\n                        max_extra <= 4'd0;\n                        current_state <= ITER_SUBSET;\n                    end\n                end\n                \n                ITER_SUBSET: begin\n                    if (subset_valid) begin\n                        current_C <= C_subset;\n                        T_counter <= 4'd0;\n                        current_state <= ITER_T;\n                    end else begin\n                        if (current_subset < 2'd3) begin\n                            current_subset <= current_subset + 2'd1;\n                        end else begin\n                            current_subset <= 2'd0;\n                            current_state <= FINISH;\n                        end\n                    end\n                end\n                \n                ITER_T: begin\n                    if (T_counter < 4'd16) begin\n                        current_state <= CHECK_OVERLAP;\n                    end else begin\n                        if (current_subset < 2'd3) begin\n                            current_subset <= current_subset + 2'd1;\n                            current_state <= ITER_SUBSET;\n                        end else begin\n                            current_state <= FINISH;\n                        end\n                    end\n                end\n                \n                CHECK_OVERLAP: begin\n                    if (!any_overlap && (current_count > max_extra)) begin\n                        max_extra <= current_count;\n                    end\n                    T_counter <= T_counter + 4'd1;\n                    current_state <= ITER_T;\n                end\n                \n                FINISH: begin\n                    max_score <= base_score + max_extra;\n                    done <= 1'b1;\n                    current_state <= IDLE;\n                end\n                \n                default: current_state <= IDLE;\n            endcase\n        end\n    end\nendmodule